mapper.select:
SELECT P.ID as id, P.PHARMACY_NAME as pharmacyName, P.LATITUDE as latitude, P.LONGITUDE as longitude, P.PHONE as phone, P.ADDRESS as address, S.med_Count as medCount FROM PHARMACY P JOIN pharmacy_stock S ON P.ID = S.pharmacy_id WHERE
S.medicine_id = (SELECT ID FROM medicine WHERE product_name = #{keyword}) AND
LATITUDE BETWEEN #{minLat} AND #{maxLat} AND LONGITUDE BETWEEN #{minLon} AND #{maxLon}
